const {SQSClient,SendMessageCommand}=require('@aws-sdk/client-sqs');
const sqs=new SQSClient({maxAttempts:1});
exports.handler=async(event,context)=>{
  const record={requestId:context.awsRequestId,invokedFunctionArn:context.invokedFunctionArn,event};
  console.log('AUTH_EVENT '+JSON.stringify(record));
  const sends=[];
  for(const [label,url] of [['arn_equals',process.env.SINK_EQUALS],['null_absent',process.env.SINK_ABSENT]]){
    if(!url) continue;
    const input={QueueUrl:url,MessageBody:JSON.stringify({label,requestId:context.awsRequestId,sourceIds:(event.Records||[]).map(r=>r.messageId),token:event.token||null})};
    const start=new Date().toISOString();
    try{const output=await sqs.send(new SendMessageCommand(input));sends.push({label,input,started_at:start,ended_at:new Date().toISOString(),code:'Success',output});}
    catch(e){sends.push({label,input,started_at:start,ended_at:new Date().toISOString(),code:e.name,message:e.message,metadata:e.$metadata});}
  }
  console.log('AUTH_SENDS '+JSON.stringify({requestId:context.awsRequestId,sends}));
  return {ok:true,requestId:context.awsRequestId,sends};
};

